(function(global){
  'use strict';
  const LF=global.LF;
  LF.state={view:'home',settings:LF.deepMerge({},LF.defaults.settings),activeProjectId:'',activeRecord:null,sidebarOpen:false,searchQuery:''};

  const views={};
  const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
  const empty=(title,body,action='')=>`<div class="empty-state"><div class="empty-state__icon" aria-hidden="true">✦</div><h2>${LF.escapeHtml(title)}</h2><p>${LF.escapeHtml(body)}</p>${action}</div>`;
  const projectPill=p=>`<span class="project-pill">${LF.escapeHtml(p?.title||'No project')}</span>`;
  const projectTypeLabel=t=>({novel:'Novel',series:'Series',short_story:'Short story',screenplay:'Screenplay',poetry:'Poetry',nonfiction:'Nonfiction',ttrpg:'TTRPG / game writing',other:'Other'}[t]||String(t||'Project').replace(/_/g,' '));
  const recordIcon=r=>r.type==='note'?(r.noteType==='journal'?'☼':'▧'):r.type==='document'?(r.docType==='chapter'?'▤':r.docType==='scene'?'✎':'▧'):r.type==='entity'?'☺':r.type==='research'?'⌕':'•';

  class App{
    constructor(){this.root=$('#viewRoot');this.inspector=$('#inspector');this.inspectorBody=$('#inspectorBody');this.searchDebounced=LF.debounce(q=>this.runGlobalSearch(q),200);}
    async init(){
      await LF.store.open();await LF.store.seed();LF.state.settings=LF.deepMerge(LF.defaults.settings,await LF.store.metaGet('settings',{}));LF.state.activeProjectId=await LF.store.metaGet('activeProjectId','');LF.a11y.apply(LF.state.settings);LF.a11y.installKeyboard();await LF.loadTemplates();this.bindShell();await this.navigate('home');$('#app').setAttribute('aria-busy','false');this.updateConnection();
      global.addEventListener('online',()=>{this.updateConnection();if(LF.api.token)LF.api.flushQueue().catch(()=>{});});global.addEventListener('offline',()=>this.updateConnection());
      LF.events.on('api:online',()=>this.updateConnection());LF.events.on('api:offline',()=>this.updateConnection());LF.events.on('editor:saved',r=>{LF.state.activeRecord=r;this.refreshInspectorIfOpen(r);});
      if(LF.state.settings.privacy.backendEnabled&&LF.api.token){LF.api.me().then(()=>this.updateConnection()).catch(()=>this.updateConnection());}
    }
    bindShell(){
      $('#primaryNav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)this.navigate(b.dataset.view);});$$('.sidebar__bottom [data-view]').forEach(b=>b.onclick=()=>this.navigate(b.dataset.view));
      $('#navToggle').onclick=()=>this.toggleSidebar();$('#themeBtn').onclick=()=>this.toggleTheme();$('#focusBtn').onclick=()=>this.toggleFocus();$('#quickCaptureBtn').onclick=()=>this.quickCapture();$('#syncBtn').onclick=()=>this.syncNow();$('#closeInspectorBtn').onclick=()=>this.closeInspector();
      $('#globalSearch').addEventListener('input',e=>this.searchDebounced(e.target.value.trim()));$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Escape'){e.target.value='';this.navigate(LF.state.view||'home');}});
      $('#importInput').addEventListener('change',e=>this.handleImport(e.target.files[0]));
    }
    async navigate(view,params={}){
      if(!views[view])view='home';if(LF.state.view==='artstudio'&&view!=='artstudio')global.LiteraryFriend?.artStudio?.park?.();if(LF.editor.record&&LF.state.view==='editor')await LF.editor.save().catch(()=>{});if(view!=='editor')LF.editor.destroy();LF.state.view=view;LF.state.activeRecord=params.record||null;$$('[data-view]').forEach(b=>b.classList.toggle('is-active',b.dataset.view===view));if(views[view])await views[view](this,params);this.root.scrollTop=0;$('#mainContent').focus({preventScroll:true});if(innerWidth<900)this.toggleSidebar(false);document.title=`${this.viewTitle(view)} — LiteraryFriend`;
    }
    viewTitle(view){return({home:'Home',projects:'Projects',manuscript:'Manuscript',notes:'Notes & Journal',outline:'Outline',characters:'Characters',world:'World & Lore',timeline:'Timeline',research:'Research',continuity:'Continuity',language:'Language Lab',revision:'Revision Lab',assistant:'Literary Assistant',bookbuilder:'Book Builder',artstudio:'Art Studio',cloud:'Cloud & Account',docs:'Docs & Licenses',trash:'Recently Deleted',settings:'Settings',editor:LF.state.activeRecord?.title||'Editor',search:'Search'}[view]||'LiteraryFriend');}
    async activeProject(){if(!LF.state.activeProjectId)return null;return LF.store.get('project',LF.state.activeProjectId);}
    async setActiveProject(id){LF.state.activeProjectId=id||'';await LF.store.metaSet('activeProjectId',LF.state.activeProjectId);LF.events.emit('project:active',id);}
    toggleSidebar(force){const open=force===undefined?!LF.state.sidebarOpen:!!force;LF.state.sidebarOpen=open;$('#sidebar').classList.toggle('is-open',open);$('#navToggle').setAttribute('aria-expanded',String(open));}
    toggleTheme(){LF.state.settings.appearance.theme=LF.state.settings.appearance.theme==='dark'?'light':'dark';this.saveSettings();}
    toggleFocus(force){const on=force===undefined?!document.documentElement.classList.contains('focus-mode'):!!force;document.documentElement.classList.toggle('focus-mode',on);$('#focusBtn').setAttribute('aria-pressed',String(on));LF.toast(on?'Focus mode on · Esc to exit':'Focus mode off');}
    async saveSettings(){await LF.store.metaSet('settings',LF.state.settings);LF.a11y.apply(LF.state.settings);if(LF.state.settings.privacy.backendEnabled&&LF.api.token)LF.api.request('settings.update',{settings:LF.state.settings}).catch(()=>{});}
    updateConnection(){const badge=$('#connectionBadge'),dot=badge.querySelector('.status-dot'),label=badge.querySelector('span:last-child');const backend=LF.state.settings.privacy.backendEnabled;if(!backend){label.textContent='Local mode';dot.dataset.state='local';}else if(!navigator.onLine){label.textContent='Offline · local saves';dot.dataset.state='offline';}else if(LF.api.token){label.textContent=`Synced account${LF.api.queue.length?` · ${LF.api.queue.length} queued`:''}`;dot.dataset.state='online';}else{label.textContent='Backend ready · sign in';dot.dataset.state='warning';}}
    async syncNow(){if(!LF.state.settings.privacy.backendEnabled){LF.toast('Backend sync is disabled in Settings.','warning');return;}if(!LF.api.token){await this.authDialog();return;}const btn=$('#syncBtn');btn.classList.add('is-spinning');try{const active=LF.state.activeRecord;if(active)await LF.api.pushRecord(active).catch(()=>{});const result=await LF.api.flushQueue();LF.toast(result.remaining?`${result.sent} synced · ${result.remaining} still queued`:'Sync complete','success');}catch(err){LF.toast(`Sync unavailable: ${err.message}`,'warning');}finally{btn.classList.remove('is-spinning');this.updateConnection();}}
    async authDialog(){const body=`<div class="tabs mini-tabs"><button type="button" data-auth-tab="login" class="is-active">Sign in</button><button type="button" data-auth-tab="register">Create account</button></div><div id="authLogin"><label class="field">Email<input id="authEmail" type="email" autocomplete="email"></label><label class="field">Password<div class="password-row"><input id="authPass" type="password" autocomplete="current-password"><button class="icon-button" id="authShow" type="button" aria-label="Show password">◉</button></div></label></div><div id="authRegister" hidden><label class="field">Display name<input id="regName"></label><label class="field">Email<input id="regEmail" type="email"></label><label class="field">Password<input id="regPass" type="password" minlength="10"></label></div>`;const result=await LF.dialog({title:'LiteraryFriend backend',body,confirmText:'Continue',onMount:root=>{root.querySelectorAll('[data-auth-tab]').forEach(b=>b.onclick=()=>{root.querySelectorAll('[data-auth-tab]').forEach(x=>x.classList.toggle('is-active',x===b));root.querySelector('#authLogin').hidden=b.dataset.authTab!=='login';root.querySelector('#authRegister').hidden=b.dataset.authTab!=='register';});root.querySelector('#authShow').onclick=()=>{const i=root.querySelector('#authPass');i.type=i.type==='password'?'text':'password';};}});if(!result)return;const isReg=!result.root.querySelector('#authRegister').hidden;try{if(isReg){await LF.api.register({displayName:result.root.querySelector('#regName').value.trim(),email:result.root.querySelector('#regEmail').value.trim(),password:result.root.querySelector('#regPass').value});}else{await LF.api.login(result.root.querySelector('#authEmail').value.trim(),result.root.querySelector('#authPass').value);}LF.state.settings.privacy.backendEnabled=true;await this.saveSettings();LF.toast('Backend account connected.','success');this.updateConnection();}catch(err){LF.toast(err.message,'danger');}}
    async quickCapture(){const project=await this.activeProject();const body=`<label class="field">Title<input id="qcTitle" value="Quick note — ${new Date().toLocaleString()}"></label><label class="field">Capture<textarea id="qcBody" rows="8" placeholder="Idea, line of dialogue, research question, scene thought…"></textarea></label><div class="check-grid"><label><input id="qcJournal" type="checkbox"> Add to writer's journal</label><label><input id="qcPin" type="checkbox"> Pin note</label></div><label class="field">Tags<input id="qcTags" placeholder="idea, dialogue, research"></label>`;const result=await LF.dialog({title:'Quick capture',body,confirmText:'Save capture',wide:true});if(!result)return;const rec=await LF.store.put({type:'note',projectId:project?.id||'',noteType:result.root.querySelector('#qcJournal').checked?'journal':'note',title:result.root.querySelector('#qcTitle').value.trim()||'Quick note',content:`<p>${LF.escapeHtml(result.root.querySelector('#qcBody').value).replace(/\n/g,'<br>')}</p>`,tags:LF.parseTags(result.root.querySelector('#qcTags').value),pinned:result.root.querySelector('#qcPin').checked});LF.toast('Capture saved.','success');if(LF.state.settings.privacy.backendEnabled&&LF.api.token)LF.api.pushRecord(rec).catch(()=>{});}
    async openRecord(record){if(!record)return;LF.state.activeRecord=record;await this.navigate('editor',{record});}
    async showInspector(record){this.inspector.hidden=false;document.documentElement.classList.add('inspector-open');await this.renderInspector(record);}
    closeInspector(){this.inspector.hidden=true;document.documentElement.classList.remove('inspector-open');}
    async refreshInspectorIfOpen(record){if(!this.inspector.hidden)await this.renderInspector(record);}
    async renderInspector(record){if(!record){this.inspectorBody.innerHTML='';return;}const attachments=await LF.store.list('attachment',{projectId:record.projectId,filter:a=>a.ownerId===record.id});const snaps=await LF.store.list('snapshot',{projectId:record.projectId,filter:s=>s.ownerId===record.id});const all=await LF.store.all();const title=record.title||record.name||'';const backlinks=all.filter(r=>r.id!==record.id&&LF.writer.extractWikiLinks(r.content||'').some(x=>x.toLowerCase()===title.toLowerCase()));const stats=LF.writer.stats(record._unlockedContent??record.content??record.description??'');this.inspectorBody.innerHTML=`<section class="inspector-section"><h3>Document</h3><dl class="detail-list"><div><dt>Words</dt><dd>${stats.words}</dd></div><div><dt>Updated</dt><dd>${LF.relativeTime(record.updatedAt)}</dd></div><div><dt>Type</dt><dd>${LF.escapeHtml(record.docType||record.noteType||record.entityType||record.type)}</dd></div><div><dt>Locked</dt><dd>${record.locked?'Yes':'No'}</dd></div></dl></section><section class="inspector-section"><h3>Tags</h3><div class="tag-cloud">${LF.tagHtml(record.tags||[])||'<span class="muted">No tags</span>'}</div></section><section class="inspector-section"><h3>Backlinks</h3>${backlinks.length?`<div class="compact-list">${backlinks.map(r=>`<button data-backlink="${r.key}" type="button">${recordIcon(r)} ${LF.escapeHtml(r.title||r.name)}</button>`).join('')}</div>`:'<p class="muted">No other LiteraryFriend item links here yet.</p>'}</section><section class="inspector-section"><h3>Attachments</h3>${attachments.length?attachments.map(a=>`<div class="attachment-row"><span>📎 ${LF.escapeHtml(a.name)}</span><button class="icon-button" data-attachment-open="${a.id}" type="button" aria-label="Open attachment">↗</button></div>`).join(''):'<p class="muted">No attachments.</p>'}</section><section class="inspector-section"><h3>Versions</h3>${snaps.length?snaps.slice(0,10).map(s=>`<button class="version-row" data-version="${s.id}" type="button"><span>${LF.formatDate(s.snapshotAt||s.createdAt,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</span><small>${LF.writer.stats(s.content).words} words</small></button>`).join(''):'<p class="muted">No snapshots yet.</p>'}</section>`;this.inspectorBody.onclick=async e=>{const bb=e.target.closest('[data-backlink]');if(bb){const r=await LF.store.getKey(bb.dataset.backlink);if(r)this.openRecord(r);}const ab=e.target.closest('[data-attachment-open]');if(ab){const b=await LF.store.getBlob(ab.dataset.attachmentOpen);if(b?.blob){const url=URL.createObjectURL(b.blob);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000);}}const vb=e.target.closest('[data-version]');if(vb){const s=await LF.store.get('snapshot',vb.dataset.version);if(!s)return;const ok=await LF.confirm('Restore this snapshot into the current editor? A new snapshot of the current text will be created first.','Restore version');if(ok){await LF.editor.snapshot();LF.editor.el.innerHTML=s.content;LF.editor.onInput();await LF.editor.save();LF.toast('Version restored.','success');}}};}
    async runGlobalSearch(query){if(!query){if(LF.state.view==='search')this.navigate('home');return;}LF.state.searchQuery=query;await this.navigate('search',{query});}
    async handleImport(file){if(!file)return;try{const text=await LF.readFile(file);if(file.name.toLowerCase().endsWith('.json')){const pack=JSON.parse(text);if(pack.format?.startsWith('literaryfriend-export')){const count=await LF.store.importAll(pack,{merge:true});LF.toast(`${count} records imported. Refreshing…`,'success');await this.navigate('home');return;}}const p=await this.activeProject();const html=file.name.toLowerCase().endsWith('.md')?LF.writer.markdownToHtml(text):`<p>${LF.escapeHtml(text).replace(/\n\n/g,'</p><p>').replace(/\n/g,'<br>')}</p>`;const rec=await LF.store.put({type:'document',projectId:p?.id||'',docType:'import',title:file.name.replace(/\.[^.]+$/,''),content:html,tags:['imported']});await this.openRecord(rec);}catch(err){LF.toast(`Import failed: ${err.message}`,'danger');}finally{$('#importInput').value='';}}
  }

  views.home=async app=>{
    const project=await app.activeProject(),projects=await LF.store.list('project',{sort:'updated-desc'}),docs=project?await LF.store.list('document',{projectId:project.id}):[],notes=project?await LF.store.list('note',{projectId:project.id}):[],issues=project?await LF.store.list('plotIssue',{projectId:project.id}):[],entities=project?await LF.store.list('entity',{projectId:project.id}):[];const allText=docs.map(d=>d.content||'').join(' '),stats=LF.writer.stats(allText),goal=Number(project?.wordGoal||0),pct=goal?Math.min(100,Math.round(stats.words/goal*100)):0;const recent=[...docs,...notes].sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,8);
    app.root.innerHTML=`<section class="view-page home-view"><header class="view-header"><div><p class="eyebrow">Writer dashboard</p><h1>${project?LF.escapeHtml(project.title):'Your writing desk'}</h1><p>${project?LF.escapeHtml(project.description||'Keep drafting, planning, and research in one connected workspace.'):'Create a project to begin.'}</p></div><div class="header-actions"><button class="button button--secondary" id="homeCapture" type="button">＋ Quick capture</button><button class="button button--primary" id="homeWrite" type="button">✎ Write</button></div></header>
      <div class="dashboard-grid">
        <article class="dashboard-card stat-card"><span class="card-kicker">Manuscript</span><strong>${stats.words.toLocaleString()}</strong><span>words across ${docs.length} documents</span>${goal?`<div class="progress"><span style="width:${pct}%"></span></div><small>${pct}% of ${goal.toLocaleString()} project goal</small>`:''}</article>
        <article class="dashboard-card stat-card"><span class="card-kicker">Story reference</span><strong>${entities.length}</strong><span>characters, places, lore & objects</span><button data-go="characters" type="button">Open story reference →</button></article>
        <article class="dashboard-card stat-card"><span class="card-kicker">Continuity</span><strong>${issues.filter(i=>i.status!=='resolved').length}</strong><span>open questions & plot issues</span><button data-go="continuity" type="button">Check continuity →</button></article>
        <article class="dashboard-card stat-card"><span class="card-kicker">Projects</span><strong>${projects.length}</strong><span>active LiteraryFriend workspaces</span><button data-go="projects" type="button">Manage projects →</button></article>
      </div>
      <div class="home-columns"><section class="panel"><div class="panel-heading"><h2>Continue writing</h2><button data-go="manuscript" type="button">View manuscript</button></div>${recent.length?`<div class="record-list">${recent.map(r=>`<button class="record-row" data-record-key="${r.key}" type="button"><span class="record-icon">${recordIcon(r)}</span><span class="record-row__main"><strong>${LF.escapeHtml(r.title)}</strong><small>${LF.escapeHtml((r.tags||[]).slice(0,3).map(t=>`#${t}`).join(' ')||r.noteType||r.docType||'document')}</small></span><span class="record-row__meta">${LF.relativeTime(r.updatedAt)}</span></button>`).join('')}</div>`:empty('Nothing written yet','Create a manuscript document or quick note to begin.')}</section>
      <section class="panel"><div class="panel-heading"><h2>Writing tools</h2></div><div class="tool-launcher"><button data-go="outline" type="button"><span>☷</span><strong>Outline</strong><small>Structure beats and scenes</small></button><button data-go="notes" type="button"><span>▧</span><strong>Notes & Journal</strong><small>Capture ideas and writing logs</small></button><button data-go="revision" type="button"><span>✓</span><strong>Revision Lab</strong><small>Readability, repetition, style signals</small></button><button data-go="assistant" type="button"><span>✦</span><strong>Literary Assistant</strong><small>Offline research & prompt context</small></button><button data-go="bookbuilder" type="button"><span>▣</span><strong>Book Builder</strong><small>Design JSON-driven interactive books</small></button></div></section></div></section>`;
    app.root.onclick=async e=>{const go=e.target.closest('[data-go]');if(go)app.navigate(go.dataset.go);const rr=e.target.closest('[data-record-key]');if(rr){const r=await LF.store.getKey(rr.dataset.recordKey);app.openRecord(r);}};$('#homeCapture').onclick=()=>app.quickCapture();$('#homeWrite').onclick=()=>app.navigate('manuscript');
  };

  views.projects=async app=>{
    const projects=await LF.store.list('project',{sort:'updated-desc'}),active=LF.state.activeProjectId;
    app.root.innerHTML=`<section class="view-page"><header class="view-header"><div><p class="eyebrow">Library</p><h1>Writing projects</h1><p>Novels, series, scripts, nonfiction, poetry, game writing, and other long-form work.</p></div><div class="header-actions"><button id="newProjectBtn" class="button button--primary" type="button">＋ New project</button></div></header>${projects.length?`<div class="project-grid">${projects.map(p=>`<article class="project-card ${p.id===active?'is-active':''}" data-project="${p.id}"><div class="project-card__top"><span class="project-type">${LF.escapeHtml(projectTypeLabel(p.projectType))}</span>${p.id===active?'<span class="active-badge">Active</span>':''}</div><h2>${LF.escapeHtml(p.title)}</h2><p>${LF.escapeHtml(p.description||'No description yet.')}</p><div class="project-card__meta"><span>${p.wordGoal?`${Number(p.wordGoal).toLocaleString()} word target`:'No word target'}</span><span>Updated ${LF.relativeTime(p.updatedAt)}</span></div><div class="project-card__actions"><button class="button button--secondary" data-open-project="${p.id}" type="button">Open</button><button class="button button--ghost" data-edit-project="${p.id}" type="button">Edit</button><button class="icon-button" data-delete-project="${p.id}" type="button" aria-label="Archive ${LF.escapeAttr(p.title)}">♲</button></div></article>`).join('')}</div>`:empty('No projects yet','Create a project for your novel, script, poetry collection, nonfiction work, or story world.')}</section>`;
    $('#newProjectBtn').onclick=()=>projectDialog(app);app.root.onclick=async e=>{const open=e.target.closest('[data-open-project]');if(open){await app.setActiveProject(open.dataset.openProject);LF.toast('Active project changed.','success');app.navigate('home');}const edit=e.target.closest('[data-edit-project]');if(edit){const p=await LF.store.get('project',edit.dataset.editProject);projectDialog(app,p);}const del=e.target.closest('[data-delete-project]');if(del){const p=await LF.store.get('project',del.dataset.deleteProject);if(await LF.confirm(`Archive “${p.title}”? You can restore it from Recently Deleted.`,`Archive project`,true)){await LF.store.softDelete('project',p.id);if(LF.state.activeProjectId===p.id){const rest=(await LF.store.list('project'))[0];await app.setActiveProject(rest?.id||'');}app.navigate('projects');}}};
  };

  async function projectDialog(app,project=null){const types=LF.templates.projectTypes?.length?LF.templates.projectTypes:[{id:'novel',name:'Novel'},{id:'series',name:'Series'},{id:'short_story',name:'Short story'},{id:'screenplay',name:'Screenplay'},{id:'poetry',name:'Poetry'},{id:'nonfiction',name:'Nonfiction'},{id:'ttrpg',name:'TTRPG / game writing'},{id:'other',name:'Other'}];const body=`<div class="form-grid"><label class="field field--wide">Project title<input id="pTitle" value="${LF.escapeAttr(project?.title||'')}"></label><label class="field">Type<select id="pType">${types.map(t=>`<option value="${t.id}" ${t.id===project?.projectType?'selected':''}>${LF.escapeHtml(t.name)}</option>`).join('')}</select></label><label class="field">Word target<input id="pGoal" type="number" min="0" step="1000" value="${project?.wordGoal||80000}"></label><label class="field field--wide">Premise<textarea id="pPremise" rows="3" placeholder="What is this work fundamentally about?">${LF.escapeHtml(project?.premise||'')}</textarea></label><label class="field field--wide">Description<textarea id="pDescription" rows="3">${LF.escapeHtml(project?.description||'')}</textarea></label><label class="field field--wide">Voice / style profile<textarea id="pStyle" rows="4" placeholder="POV, tense, tone, sentence texture, dialogue rules, imagery preferences…">${LF.escapeHtml(project?.styleProfile||'')}</textarea></label></div>`;const result=await LF.dialog({title:project?'Edit project':'New writing project',body,confirmText:project?'Save changes':'Create project',wide:true});if(!result)return;const title=result.root.querySelector('#pTitle').value.trim();if(!title){LF.toast('Project title is required.','warning');return;}const rec=await LF.store.put({...project,type:'project',title,projectType:result.root.querySelector('#pType').value,wordGoal:Number(result.root.querySelector('#pGoal').value||0),premise:result.root.querySelector('#pPremise').value.trim(),description:result.root.querySelector('#pDescription').value.trim(),styleProfile:result.root.querySelector('#pStyle').value.trim(),status:'active'});if(!project)await app.setActiveProject(rec.id);if(LF.state.settings.privacy.backendEnabled&&LF.api.token)LF.api.pushRecord(rec).catch(()=>{});LF.toast(project?'Project updated.':'Project created.','success');app.navigate('projects');}

  views.manuscript=async app=>{
    const p=await app.activeProject();if(!p){app.root.innerHTML=empty('Choose a project','Create or open a writing project before building a manuscript.','<button id="goProjects" class="button button--primary" type="button">Projects</button>');$('#goProjects').onclick=()=>app.navigate('projects');return;}const docs=await LF.store.list('document',{projectId:p.id,sort:'order'});const chapters=docs.filter(d=>d.docType==='chapter'),scenes=docs.filter(d=>d.docType==='scene'),other=docs.filter(d=>!['chapter','scene'].includes(d.docType));const total=LF.writer.stats(docs.map(d=>d.content||'').join(' ')).words;
    app.root.innerHTML=`<section class="view-page manuscript-view"><header class="view-header"><div><p class="eyebrow">${LF.escapeHtml(p.title)}</p><h1>Manuscript</h1><p>${total.toLocaleString()} words across ${docs.length} document${docs.length===1?'':'s'}.</p></div><div class="header-actions"><button id="newChapterBtn" class="button button--secondary" type="button">＋ Chapter</button><button id="newSceneBtn" class="button button--primary" type="button">＋ Scene</button><button id="importDocBtn" class="button button--ghost" type="button">Import</button></div></header>
      <div class="manuscript-layout"><section class="panel manuscript-tree"><div class="panel-heading"><h2>Draft order</h2><button id="newDocBtn" type="button">＋ Other</button></div>${docs.length?`<div id="manuscriptList" class="sortable-list">${docs.map((d,i)=>`<article class="manuscript-item" data-doc="${d.id}" draggable="true"><span class="drag-handle" aria-hidden="true">⠿</span><button class="manuscript-open" data-open="${d.id}" type="button"><span>${recordIcon(d)}</span><span><strong>${LF.escapeHtml(d.title)}</strong><small>${LF.writer.stats(d.content||'').words} words · ${LF.escapeHtml(d.status||'draft')}</small></span></button><button class="icon-button" data-doc-menu="${d.id}" type="button" aria-label="Document actions">⋯</button></article>`).join('')}</div>`:empty('No manuscript documents','Add a chapter or scene. You can reorder documents by dragging them.')}</section>
      <aside class="panel manuscript-overview"><div class="panel-heading"><h2>Project context</h2></div><dl class="detail-list"><div><dt>Project</dt><dd>${LF.escapeHtml(p.title)}</dd></div><div><dt>Type</dt><dd>${LF.escapeHtml(projectTypeLabel(p.projectType))}</dd></div><div><dt>Chapters</dt><dd>${chapters.length}</dd></div><div><dt>Scenes</dt><dd>${scenes.length}</dd></div><div><dt>Other docs</dt><dd>${other.length}</dd></div><div><dt>Word target</dt><dd>${Number(p.wordGoal||0).toLocaleString()}</dd></div></dl><h3>Premise</h3><p>${LF.escapeHtml(p.premise||'Add a project premise from Projects → Edit.')}</p><h3>Style profile</h3><p>${LF.escapeHtml(p.styleProfile||'Add voice and style notes so revision and assistant tools can preserve intentional choices.')}</p><button class="button button--secondary" id="scenePreflightBtn" type="button">Scene pre-flight checklist</button></aside></div></section>`;
    $('#newChapterBtn').onclick=()=>newManuscriptDoc(app,p,'chapter',docs);$('#newSceneBtn').onclick=()=>newManuscriptDoc(app,p,'scene',docs);$('#newDocBtn').onclick=()=>newManuscriptDoc(app,p,'document',docs);$('#importDocBtn').onclick=()=>$('#importInput').click();$('#scenePreflightBtn').onclick=()=>scenePreflightDialog(p);
    app.root.onclick=async e=>{const open=e.target.closest('[data-open]');if(open){const r=await LF.store.get('document',open.dataset.open);app.openRecord(r);}const menu=e.target.closest('[data-doc-menu]');if(menu){const r=await LF.store.get('document',menu.dataset.docMenu);docActions(app,r);}};enableSort($('#manuscriptList'),async ids=>{for(let i=0;i<ids.length;i++){const r=await LF.store.get('document',ids[i]);await LF.store.put({...r,sortOrder:i*10});}});
  };

  async function newManuscriptDoc(app,p,type,docs){const label=type==='chapter'?'Chapter':type==='scene'?'Scene':'Document';const body=`<label class="field">${label} title<input id="docTitle" value="${label} ${type==='chapter'?docs.filter(d=>d.docType==='chapter').length+1:''}"></label>${type==='scene'?'<label class="field">Point of view<input id="docPov" placeholder="Character or narrative POV"></label><label class="field">Scene objective<textarea id="docObjective" rows="2"></textarea></label><label class="field">Conflict / pressure<textarea id="docConflict" rows="2"></textarea></label>':''}<label class="field">Word target<input id="docGoal" type="number" min="0" value="${type==='scene'?1200:3000}"></label>`;const result=await LF.dialog({title:`New ${label.toLowerCase()}`,body,confirmText:'Create & write'});if(!result)return;const rec=await LF.store.put({type:'document',projectId:p.id,docType:type,title:result.root.querySelector('#docTitle').value.trim()||`Untitled ${label}`,content:'',pov:result.root.querySelector('#docPov')?.value.trim()||'',objective:result.root.querySelector('#docObjective')?.value.trim()||'',conflict:result.root.querySelector('#docConflict')?.value.trim()||'',wordGoal:Number(result.root.querySelector('#docGoal').value||0),sortOrder:docs.length*10,status:'draft',tags:[]});app.openRecord(rec);}
  async function docActions(app,r){await LF.dialog({title:r.title,body:`<div class="action-list"><button data-doc-action="duplicate" type="button">Duplicate document</button><button data-doc-action="snapshot" type="button">Create version snapshot</button><button data-doc-action="markdown" type="button">Export Markdown</button><button data-doc-action="delete" class="danger-text" type="button">Move to Recently Deleted</button></div>`,confirmText:'Close',cancelText:'Close',onMount:root=>{root.querySelector('.modal__footer [data-confirm]').hidden=true;root.querySelector('.action-list').onclick=async e=>{const b=e.target.closest('[data-doc-action]');if(!b)return;const a=b.dataset.docAction;if(a==='duplicate'){await LF.store.put({...r,id:undefined,key:undefined,backendId:'',title:`${r.title} copy`,sortOrder:Number(r.sortOrder||0)+1});LF.toast('Document duplicated.','success');}if(a==='snapshot'){await LF.store.put({type:'snapshot',projectId:r.projectId,ownerType:'document',ownerId:r.id,title:r.title,content:r.content||'',tags:r.tags||[],snapshotAt:LF.now()});LF.toast('Version snapshot created.','success');}if(a==='markdown')LF.download(`${LF.slug(r.title)}.md`,LF.writer.exportMarkdown(r),'text/markdown');if(a==='delete')await LF.store.softDelete('document',r.id);root.remove();app.navigate('manuscript');};}});}
  async function scenePreflightDialog(project){const checks=LF.writer.preflight(project,{});await LF.dialog({title:'Scene pre-flight',body:`<p>Use this as a fast planning pass before drafting.</p><div class="checklist-panel">${checks.map(c=>`<label><input type="checkbox" ${c.done?'checked':''}> ${LF.escapeHtml(c.label)}</label>`).join('')}</div>`,confirmText:'Done',cancelText:'Close'});}
  function enableSort(list,onSave){if(!list)return;let dragging=null;list.addEventListener('dragstart',e=>{dragging=e.target.closest('[draggable="true"]');dragging?.classList.add('is-dragging');});list.addEventListener('dragend',async()=>{dragging?.classList.remove('is-dragging');dragging=null;await onSave([...list.children].map(x=>x.dataset.doc));});list.addEventListener('dragover',e=>{e.preventDefault();const after=[...list.querySelectorAll('[draggable="true"]:not(.is-dragging)')].find(el=>{const r=el.getBoundingClientRect();return e.clientY<r.top+r.height/2;});if(dragging)list.insertBefore(dragging,after||null);});}

  views.notes=async app=>{
    const p=await app.activeProject(),notes=await LF.store.list('note',{projectId:p?.id||undefined,sort:'updated-desc'}),folders=await LF.store.list('noteFolder',{projectId:p?.id||undefined,sort:'title-asc'}),smart=await LF.store.list('smartFolder',{projectId:p?.id||undefined,sort:'title-asc'});const pinned=notes.filter(n=>n.pinned),journal=notes.filter(n=>n.noteType==='journal');
    app.root.innerHTML=`<section class="view-page notes-view"><header class="view-header"><div><p class="eyebrow">Commonplace book + writer's journal</p><h1>Notes & Journal</h1><p>Quick ideas, long notes, writing logs, images, scans, audio, checklists, and linked research.</p></div><div class="header-actions"><button id="newFolderBtn" class="button button--ghost" type="button">＋ Folder</button><button id="newJournalBtn" class="button button--secondary" type="button">☼ Journal entry</button><button id="newNoteBtn" class="button button--primary" type="button">＋ Note</button></div></header>
      <div class="notes-layout"><aside class="notes-folders panel"><div class="note-filter-group"><h2>Library</h2><button data-note-filter="all" class="is-active" type="button">All notes <span>${notes.length}</span></button><button data-note-filter="pinned" type="button">Pinned <span>${pinned.length}</span></button><button data-note-filter="journal" type="button">Writer's journal <span>${journal.length}</span></button><button data-note-filter="locked" type="button">Locked <span>${notes.filter(n=>n.locked).length}</span></button><button data-note-filter="attachments" type="button">With attachments</button></div><div class="note-filter-group"><div class="panel-heading"><h2>Folders</h2></div>${folders.map(f=>`<button data-folder="${f.id}" type="button">📁 ${LF.escapeHtml(f.title)}</button>`).join('')||'<p class="muted small">No folders yet.</p>'}</div><div class="note-filter-group"><div class="panel-heading"><h2>Smart folders</h2><button id="newSmartBtn" type="button">＋</button></div>${smart.map(f=>`<button data-smart="${f.id}" type="button">⌕ ${LF.escapeHtml(f.title)}</button>`).join('')||'<p class="muted small">Saved filters appear here.</p>'}</div></aside>
      <section class="panel note-browser"><div class="note-browser__toolbar"><input id="noteSearch" type="search" placeholder="Search this note library"><select id="noteSort"><option value="updated-desc">Recently edited</option><option value="created-desc">Recently created</option><option value="title-asc">Title</option></select></div><div id="noteList" class="note-card-list"></div></section></div></section>`;
    const list=$('#noteList');let filter='all';const render=async()=>{let rows=[...notes];const q=$('#noteSearch').value.trim().toLowerCase();if(filter==='pinned')rows=rows.filter(n=>n.pinned);else if(filter==='journal')rows=rows.filter(n=>n.noteType==='journal');else if(filter==='locked')rows=rows.filter(n=>n.locked);else if(filter.startsWith('folder:'))rows=rows.filter(n=>n.folderId===filter.split(':')[1]);else if(filter.startsWith('smart:')){const sf=await LF.store.get('smartFolder',filter.split(':')[1]);rows=applySmartFolder(rows,sf);}if(filter==='attachments'){const at=await LF.store.list('attachment',{projectId:p?.id});const ids=new Set(at.map(a=>a.ownerId));rows=rows.filter(n=>ids.has(n.id));}if(q)rows=rows.filter(n=>`${n.title} ${LF.stripHtml(n.content||'')} ${(n.tags||[]).join(' ')}`.toLowerCase().includes(q));const sort=$('#noteSort').value;if(sort==='title-asc')rows.sort((a,b)=>a.title.localeCompare(b.title));else if(sort==='created-desc')rows.sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));else rows.sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));list.innerHTML=rows.length?rows.map(n=>`<article class="note-card" data-note="${n.id}"><button class="note-card__open" data-open-note="${n.id}" type="button"><div class="note-card__title"><span>${n.pinned?'★ ':''}${n.noteType==='journal'?'☼ ':'▧ '}${LF.escapeHtml(n.title)}</span>${n.locked?'<span title="Encrypted">🔒</span>':''}</div><p>${n.locked?'Encrypted note body':LF.escapeHtml(LF.stripHtml(n.content||'').slice(0,220)||'Empty note')}</p><div class="note-card__meta"><span>${LF.relativeTime(n.updatedAt)}</span><span>${LF.tagHtml((n.tags||[]).slice(0,3))}</span></div></button><button class="icon-button" data-note-menu="${n.id}" type="button" aria-label="Note actions">⋯</button></article>`).join(''):empty('No notes match','Try another filter or create a new note.');};await render();$('#noteSearch').oninput=()=>render();$('#noteSort').onchange=()=>render();$$('[data-note-filter]').forEach(b=>b.onclick=()=>{$$('[data-note-filter]').forEach(x=>x.classList.toggle('is-active',x===b));filter=b.dataset.noteFilter;render();});$$('[data-folder]').forEach(b=>b.onclick=()=>{filter=`folder:${b.dataset.folder}`;render();});$$('[data-smart]').forEach(b=>b.onclick=()=>{filter=`smart:${b.dataset.smart}`;render();});$('#newNoteBtn').onclick=()=>newNote(app,p,'note');$('#newJournalBtn').onclick=()=>newNote(app,p,'journal');$('#newFolderBtn').onclick=()=>newNoteFolder(app,p);$('#newSmartBtn').onclick=()=>newSmartFolder(app,p);list.onclick=async e=>{const b=e.target.closest('[data-open-note]');if(b){const n=await LF.store.get('note',b.dataset.openNote);app.openRecord(n);}const m=e.target.closest('[data-note-menu]');if(m){const n=await LF.store.get('note',m.dataset.noteMenu);await noteMenu(app,n);}};
  };
  function applySmartFolder(rows,sf){if(!sf)return rows;const f=sf.filters||{};return rows.filter(n=>(!f.tags?.length||f.tags.every(t=>(n.tags||[]).includes(t)))&&(f.pinned===undefined||!!n.pinned===!!f.pinned)&&(!f.noteType||n.noteType===f.noteType)&&(!f.updatedDays||Date.now()-new Date(n.updatedAt).getTime()<=Number(f.updatedDays)*86400000));}
  async function newNote(app,p,noteType){const templates=(LF.templates.documentTemplates||[]).filter(t=>t.type==='note'||t.type==='journal');const body=`<label class="field">Title<input id="nTitle" value="${noteType==='journal'?`Writer's Log — ${new Date().toLocaleDateString()}`:'Untitled note'}"></label><label class="field">Template<select id="nTemplate"><option value="">Blank</option>${templates.map(t=>`<option value="${t.id}">${LF.escapeHtml(t.name)}</option>`).join('')}</select></label>`;const result=await LF.dialog({title:noteType==='journal'?'New journal entry':'New note',body,confirmText:'Create'});if(!result)return;const tid=result.root.querySelector('#nTemplate').value,t=templates.find(x=>x.id===tid);const rec=await LF.store.put({type:'note',projectId:p?.id||'',noteType,title:result.root.querySelector('#nTitle').value.trim()||'Untitled note',content:t?.content||'',tags:noteType==='journal'?['journal']:[],pinned:false});app.openRecord(rec);}
  async function newNoteFolder(app,p){const result=await LF.dialog({title:'New notes folder',body:'<label class="field">Folder name<input id="folderTitle"></label>',confirmText:'Create'});if(!result)return;await LF.store.put({type:'noteFolder',projectId:p?.id||'',title:result.root.querySelector('#folderTitle').value.trim()||'New folder'});app.navigate('notes');}
  async function newSmartFolder(app,p){const result=await LF.dialog({title:'New smart folder',body:'<label class="field">Name<input id="sfTitle" value="Recent ideas"></label><label class="field">Required tags<input id="sfTags" placeholder="idea, scene"></label><div class="check-grid"><label><input id="sfPinned" type="checkbox"> Pinned only</label><label><input id="sfJournal" type="checkbox"> Journal entries only</label></div><label class="field">Edited within days<input id="sfDays" type="number" min="0" value="30"></label>',confirmText:'Create'});if(!result)return;await LF.store.put({type:'smartFolder',projectId:p?.id||'',title:result.root.querySelector('#sfTitle').value.trim()||'Smart folder',filters:{tags:LF.parseTags(result.root.querySelector('#sfTags').value),pinned:result.root.querySelector('#sfPinned').checked?true:undefined,noteType:result.root.querySelector('#sfJournal').checked?'journal':'',updatedDays:Number(result.root.querySelector('#sfDays').value||0)}});app.navigate('notes');}
  async function noteMenu(app,n){const body=`<div class="action-list"><button data-note-action="pin" type="button">${n.pinned?'Unpin':'Pin'} note</button><button data-note-action="duplicate" type="button">Duplicate note</button><button data-note-action="export" type="button">Export Markdown</button><button data-note-action="delete" class="danger-text" type="button">Move to Recently Deleted</button></div>`;const root=document.createElement('div');const result=await LF.dialog({title:n.title,body,confirmText:'Close',cancelText:'Close',onMount:r=>{r.querySelector('.modal__footer [data-confirm]').hidden=true;r.querySelector('.action-list').onclick=async e=>{const b=e.target.closest('[data-note-action]');if(!b)return;const a=b.dataset.noteAction;if(a==='pin')await LF.store.put({...n,pinned:!n.pinned});if(a==='duplicate')await LF.store.put({...n,id:undefined,key:undefined,title:`${n.title} copy`,pinned:false,backendId:''});if(a==='export')LF.download(`${LF.slug(n.title)}.md`,LF.writer.exportMarkdown(n),'text/markdown');if(a==='delete')await LF.store.softDelete('note',n.id);r.remove();app.navigate('notes');};}});return result;}

  views.outline=async app=>{
    const p=await app.activeProject();if(!p){app.root.innerHTML=empty('Choose a project','Outlines belong to a writing project.');return;}const beats=await LF.store.list('outlineBeat',{projectId:p.id,sort:'order'});const docs=await LF.store.list('document',{projectId:p.id,sort:'order'});app.root.innerHTML=`<section class="view-page"><header class="view-header"><div><p class="eyebrow">${LF.escapeHtml(p.title)}</p><h1>Outline & story board</h1><p>Plan acts, beats, chapters, and scenes without forcing one story formula.</p></div><div class="header-actions"><button id="structureBtn" class="button button--ghost" type="button">Apply structure</button><button id="newBeatBtn" class="button button--primary" type="button">＋ Beat</button></div></header><div class="outline-board" id="outlineBoard">${beats.length?beats.map((b,i)=>outlineCard(b,i,docs)).join(''):empty('No outline beats yet','Add beats manually or start from a flexible structure template.')}</div></section>`;$('#newBeatBtn').onclick=()=>beatDialog(app,p,docs);$('#structureBtn').onclick=()=>structureDialog(app,p,beats);$('#outlineBoard').onclick=async e=>{const edit=e.target.closest('[data-edit-beat]');if(edit){const b=await LF.store.get('outlineBeat',edit.dataset.editBeat);beatDialog(app,p,docs,b);}const del=e.target.closest('[data-delete-beat]');if(del&&await LF.confirm('Delete this outline beat?','Delete beat',true)){await LF.store.softDelete('outlineBeat',del.dataset.deleteBeat);app.navigate('outline');}const open=e.target.closest('[data-linked-doc]');if(open){const d=await LF.store.get('document',open.dataset.linkedDoc);if(d)app.openRecord(d);}};
  };
  function outlineCard(b,i,docs){const d=docs.find(x=>x.id===b.documentId);return `<article class="outline-card"><div class="outline-card__num">${i+1}</div><div class="outline-card__body"><div class="outline-card__top"><span class="beat-kind">${LF.escapeHtml(b.beatType||'Beat')}</span><span>${LF.escapeHtml(b.act||'')}</span></div><h2>${LF.escapeHtml(b.title)}</h2><p>${LF.escapeHtml(b.summary||'')}</p><div class="tag-cloud">${LF.tagHtml(b.tags||[])}</div>${d?`<button class="linked-doc" data-linked-doc="${d.id}" type="button">✎ ${LF.escapeHtml(d.title)}</button>`:''}</div><div class="outline-card__actions"><button class="icon-button" data-edit-beat="${b.id}" type="button" aria-label="Edit beat">✎</button><button class="icon-button" data-delete-beat="${b.id}" type="button" aria-label="Delete beat">×</button></div></article>`;}
  async function beatDialog(app,p,docs,beat=null){const result=await LF.dialog({title:beat?'Edit outline beat':'New outline beat',body:`<div class="form-grid"><label class="field">Title<input id="bTitle" value="${LF.escapeAttr(beat?.title||'')}"></label><label class="field">Act / section<input id="bAct" value="${LF.escapeAttr(beat?.act||'')}"></label><label class="field">Beat type<input id="bType" value="${LF.escapeAttr(beat?.beatType||'Scene beat')}"></label><label class="field">Linked manuscript document<select id="bDoc"><option value="">None</option>${docs.map(d=>`<option value="${d.id}" ${d.id===beat?.documentId?'selected':''}>${LF.escapeHtml(d.title)}</option>`).join('')}</select></label><label class="field field--wide">Summary<textarea id="bSummary" rows="4">${LF.escapeHtml(beat?.summary||'')}</textarea></label><label class="field field--wide">Tags<input id="bTags" value="${LF.escapeAttr((beat?.tags||[]).join(', '))}"></label></div>`,confirmText:'Save beat',wide:true});if(!result)return;const existing=await LF.store.list('outlineBeat',{projectId:p.id});await LF.store.put({...beat,type:'outlineBeat',projectId:p.id,title:result.root.querySelector('#bTitle').value.trim()||'Untitled beat',act:result.root.querySelector('#bAct').value.trim(),beatType:result.root.querySelector('#bType').value.trim(),documentId:result.root.querySelector('#bDoc').value,summary:result.root.querySelector('#bSummary').value.trim(),tags:LF.parseTags(result.root.querySelector('#bTags').value),sortOrder:beat?.sortOrder??existing.length*10});app.navigate('outline');}
  async function structureDialog(app,p,existing){const structures=LF.templates.storyStructures||[];const result=await LF.dialog({title:'Flexible structure starter',body:`<p>These are planning scaffolds, not rules. Existing beats will not be replaced.</p><label class="field">Structure<select id="structureChoice">${structures.map(s=>`<option value="${s.id}">${LF.escapeHtml(s.name)}</option>`).join('')}</select></label>`,confirmText:'Add beats'});if(!result)return;const s=structures.find(x=>x.id===result.root.querySelector('#structureChoice').value);if(!s)return;for(let i=0;i<s.beats.length;i++)await LF.store.put({type:'outlineBeat',projectId:p.id,title:s.beats[i].title,summary:s.beats[i].description||'',act:s.beats[i].section||'',beatType:'Structure beat',sortOrder:(existing.length+i)*10,tags:['structure']});app.navigate('outline');}

  views.characters=app=>entityView(app,'character','Characters','Track voice, wants, needs, arcs, relationships, and consistency.');
  views.world=app=>entityView(app,'world','World & Lore','Places, organizations, cultures, objects, creatures, systems, and setting rules.');
  async function entityView(app,scope,title,desc){const p=await app.activeProject();if(!p){app.root.innerHTML=empty('Choose a project',`${title} belong to a writing project.`);return;}const all=await LF.store.list('entity',{projectId:p.id,sort:'title-asc'});const kinds=scope==='character'?['character']:['location','organization','culture','object','creature','faction','system','other'];let rows=all.filter(e=>kinds.includes(e.entityType));app.root.innerHTML=`<section class="view-page"><header class="view-header"><div><p class="eyebrow">Story reference</p><h1>${title}</h1><p>${desc}</p></div><div class="header-actions"><button id="newEntityBtn" class="button button--primary" type="button">＋ ${scope==='character'?'Character':'World entry'}</button></div></header><div class="entity-toolbar"><input id="entitySearch" type="search" placeholder="Search ${title.toLowerCase()}">${scope!=='character'?`<select id="entityKind"><option value="all">All types</option>${kinds.map(k=>`<option value="${k}">${LF.escapeHtml(k[0].toUpperCase()+k.slice(1))}</option>`).join('')}</select>`:''}</div><div id="entityGrid" class="entity-grid"></div></section>`;const grid=$('#entityGrid');const render=()=>{const q=$('#entitySearch').value.toLowerCase();let list=rows.filter(e=>`${e.name} ${e.description||''} ${(e.tags||[]).join(' ')}`.toLowerCase().includes(q));if($('#entityKind')&&$('#entityKind').value!=='all')list=list.filter(e=>e.entityType===$('#entityKind').value);grid.innerHTML=list.length?list.map(e=>`<article class="entity-card"><div class="entity-card__type">${LF.escapeHtml(e.entityType)}</div><h2>${LF.escapeHtml(e.name)}</h2><p>${LF.escapeHtml((e.description||'').slice(0,260)||'No description yet.')}</p>${e.aliases?.length?`<small>Also: ${LF.escapeHtml(e.aliases.join(', '))}</small>`:''}<div class="tag-cloud">${LF.tagHtml(e.tags||[])}</div><div class="entity-card__actions"><button data-edit-entity="${e.id}" class="button button--secondary" type="button">Edit</button><button data-entity-note="${e.id}" class="button button--ghost" type="button">Open reference note</button></div></article>`).join(''):empty(`No ${title.toLowerCase()} yet`,'Create the first reference entry.');};render();$('#entitySearch').oninput=render;if($('#entityKind'))$('#entityKind').onchange=render;$('#newEntityBtn').onclick=()=>entityDialog(app,p,scope==='character'?'character':'location');grid.onclick=async e=>{const edit=e.target.closest('[data-edit-entity]');if(edit){entityDialog(app,p,null,await LF.store.get('entity',edit.dataset.editEntity));}const note=e.target.closest('[data-entity-note]');if(note){const ent=await LF.store.get('entity',note.dataset.entityNote);let n=(await LF.store.list('note',{projectId:p.id,filter:x=>x.entityId===ent.id}))[0];if(!n)n=await LF.store.put({type:'note',projectId:p.id,noteType:'reference',entityId:ent.id,title:`Reference — ${ent.name}`,content:`<h1>${LF.escapeHtml(ent.name)}</h1><p>${LF.escapeHtml(ent.description||'')}</p>`,tags:[ent.entityType]});app.openRecord(n);}};}
  async function entityDialog(app,p,defaultType,ent=null){const types=['character','location','organization','culture','object','creature','faction','system','other'];const attrs=ent?.attributes||{};const result=await LF.dialog({title:ent?'Edit story reference':'New story reference',wide:true,body:`<div class="form-grid"><label class="field">Type<select id="eType">${types.map(t=>`<option value="${t}" ${t===(ent?.entityType||defaultType)?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></label><label class="field">Name<input id="eName" value="${LF.escapeAttr(ent?.name||'')}"></label><label class="field field--wide">Aliases<input id="eAliases" value="${LF.escapeAttr((ent?.aliases||[]).join(', '))}" placeholder="nicknames, former names, titles"></label><label class="field field--wide">Description<textarea id="eDesc" rows="5">${LF.escapeHtml(ent?.description||'')}</textarea></label><label class="field">Role / function<input id="eRole" value="${LF.escapeAttr(attrs.role||'')}"></label><label class="field">Voice / texture<input id="eVoice" value="${LF.escapeAttr(attrs.voice||'')}"></label><label class="field">Want / purpose<input id="eWant" value="${LF.escapeAttr(attrs.want||'')}"></label><label class="field">Need / hidden pressure<input id="eNeed" value="${LF.escapeAttr(attrs.need||'')}"></label><label class="field field--wide">Arc / change<textarea id="eArc" rows="3">${LF.escapeHtml(attrs.arc||'')}</textarea></label><label class="field field--wide">Rules / constraints<textarea id="eRules" rows="3">${LF.escapeHtml(attrs.rules||'')}</textarea></label><label class="field field--wide">Tags<input id="eTags" value="${LF.escapeAttr((ent?.tags||[]).join(', '))}"></label></div>`,confirmText:'Save reference'});if(!result)return;const rec=await LF.store.put({...ent,type:'entity',projectId:p.id,entityType:result.root.querySelector('#eType').value,name:result.root.querySelector('#eName').value.trim()||'Untitled',aliases:LF.parseTags(result.root.querySelector('#eAliases').value),description:result.root.querySelector('#eDesc').value.trim(),attributes:{...attrs,role:result.root.querySelector('#eRole').value.trim(),voice:result.root.querySelector('#eVoice').value.trim(),want:result.root.querySelector('#eWant').value.trim(),need:result.root.querySelector('#eNeed').value.trim(),arc:result.root.querySelector('#eArc').value.trim(),rules:result.root.querySelector('#eRules').value.trim()},tags:LF.parseTags(result.root.querySelector('#eTags').value)});if(LF.state.settings.privacy.backendEnabled&&LF.api.token)LF.api.pushRecord(rec).catch(()=>{});app.navigate(rec.entityType==='character'?'characters':'world');}

  views.timeline=async app=>{const p=await app.activeProject();if(!p){app.root.innerHTML=empty('Choose a project','Timeline events belong to a writing project.');return;}const events=await LF.store.list('timeline',{projectId:p.id,sort:'order'});app.root.innerHTML=`<section class="view-page"><header class="view-header"><div><p class="eyebrow">Chronology</p><h1>Timeline</h1><p>Track dates, relative order, ages, discoveries, wars, journeys, backstory, and scene chronology.</p></div><div class="header-actions"><button id="newEventBtn" class="button button--primary" type="button">＋ Event</button></div></header><div class="timeline-list">${events.length?events.map((ev,i)=>`<article class="timeline-event"><div class="timeline-marker">${i+1}</div><div class="timeline-content"><span class="timeline-date">${LF.escapeHtml(ev.dateLabel||`Order ${ev.sortOrder??i}`)}</span><h2>${LF.escapeHtml(ev.title)}</h2><p>${LF.escapeHtml(ev.description||'')}</p><div>${LF.tagHtml(ev.tags||[])}</div></div><button class="icon-button" data-edit-event="${ev.id}" type="button" aria-label="Edit event">✎</button></article>`).join(''):empty('No timeline events','Add events even if your story uses relative or invented dates.')}</div></section>`;$('#newEventBtn').onclick=()=>timelineDialog(app,p,events);app.root.onclick=async e=>{const b=e.target.closest('[data-edit-event]');if(b)timelineDialog(app,p,events,await LF.store.get('timeline',b.dataset.editEvent));};};
  async function timelineDialog(app,p,events,ev=null){const result=await LF.dialog({title:ev?'Edit timeline event':'New timeline event',wide:true,body:`<div class="form-grid"><label class="field">Title<input id="tTitle" value="${LF.escapeAttr(ev?.title||'')}"></label><label class="field">Date / story-time label<input id="tDate" value="${LF.escapeAttr(ev?.dateLabel||'')}"></label><label class="field">Sort order<input id="tOrder" type="number" value="${ev?.sortOrder??events.length*10}"></label><label class="field">Participants<input id="tPeople" value="${LF.escapeAttr((ev?.participants||[]).join(', '))}"></label><label class="field field--wide">Description<textarea id="tDesc" rows="5">${LF.escapeHtml(ev?.description||'')}</textarea></label><label class="field field--wide">Tags<input id="tTags" value="${LF.escapeAttr((ev?.tags||[]).join(', '))}"></label></div>`,confirmText:'Save event'});if(!result)return;const rec=await LF.store.put({...ev,type:'timeline',projectId:p.id,title:result.root.querySelector('#tTitle').value.trim()||'Untitled event',dateLabel:result.root.querySelector('#tDate').value.trim(),sortOrder:Number(result.root.querySelector('#tOrder').value||0),participants:LF.parseTags(result.root.querySelector('#tPeople').value),description:result.root.querySelector('#tDesc').value.trim(),tags:LF.parseTags(result.root.querySelector('#tTags').value)});if(LF.state.settings.privacy.backendEnabled&&LF.api.token)LF.api.pushRecord(rec).catch(()=>{});app.navigate('timeline');}

  views.research=async app=>{const p=await app.activeProject();const items=await LF.store.list('research',{projectId:p?.id||undefined,sort:'updated-desc'});app.root.innerHTML=`<section class="view-page"><header class="view-header"><div><p class="eyebrow">Source cabinet</p><h1>Research</h1><p>Keep sources, quotes, links, questions, and your own notes beside the writing they support.</p></div><div class="header-actions"><button id="newResearchBtn" class="button button--primary" type="button">＋ Source</button></div></header><div class="research-toolbar"><input id="researchSearch" type="search" placeholder="Search research"></div><div id="researchGrid" class="research-grid"></div></section>`;const grid=$('#researchGrid');const render=()=>{const q=$('#researchSearch').value.toLowerCase();const list=items.filter(r=>`${r.title} ${r.author||''} ${r.notes||''} ${(r.tags||[]).join(' ')}`.toLowerCase().includes(q));grid.innerHTML=list.length?list.map(r=>`<article class="research-card"><div class="research-card__top"><span>${LF.escapeHtml(r.sourceType||'source')}</span>${r.url?`<a href="${LF.escapeAttr(r.url)}" target="_blank" rel="noopener">Open source ↗</a>`:''}</div><h2>${LF.escapeHtml(r.title)}</h2><p>${LF.escapeHtml((r.notes||'').slice(0,320)||'No research notes yet.')}</p>${r.quote?`<blockquote>${LF.escapeHtml(r.quote.slice(0,260))}</blockquote>`:''}<div>${LF.tagHtml(r.tags||[])}</div><div class="research-card__actions"><button data-edit-research="${r.id}" class="button button--secondary" type="button">Edit</button><button data-cite-research="${r.id}" class="button button--ghost" type="button">Citation</button></div></article>`).join(''):empty('No research saved','Add a source, interview note, link, book, article, archive, image reference, or research question.');};render();$('#researchSearch').oninput=render;$('#newResearchBtn').onclick=()=>researchDialog(app,p);grid.onclick=async e=>{const edit=e.target.closest('[data-edit-research]');if(edit)researchDialog(app,p,await LF.store.get('research',edit.dataset.editResearch));const cite=e.target.closest('[data-cite-research]');if(cite){const r=await LF.store.get('research',cite.dataset.citeResearch);citationDialog(r);}};};
  async function researchDialog(app,p,r=null){const result=await LF.dialog({title:r?'Edit research source':'New research source',wide:true,body:`<div class="form-grid"><label class="field">Title<input id="rTitle" value="${LF.escapeAttr(r?.title||'')}"></label><label class="field">Source type<select id="rType"><option>web</option><option>book</option><option>article</option><option>archive</option><option>interview</option><option>video</option><option>image</option><option>primary source</option><option>question</option><option>other</option></select></label><label class="field">Author / creator<input id="rAuthor" value="${LF.escapeAttr(r?.author||'')}"></label><label class="field">Publication / site<input id="rPub" value="${LF.escapeAttr(r?.publication||'')}"></label><label class="field">Published date<input id="rDate" value="${LF.escapeAttr(r?.publishedAt||'')}"></label><label class="field">URL<input id="rUrl" type="url" value="${LF.escapeAttr(r?.url||'')}"></label><label class="field field--wide">Important quote<textarea id="rQuote" rows="3">${LF.escapeHtml(r?.quote||'')}</textarea></label><label class="field field--wide">Research notes<textarea id="rNotes" rows="7">${LF.escapeHtml(r?.notes||'')}</textarea></label><label class="field field--wide">Tags<input id="rTags" value="${LF.escapeAttr((r?.tags||[]).join(', '))}"></label></div>`,confirmText:'Save source'});if(!result)return;await LF.store.put({...r,type:'research',projectId:p?.id||'',title:result.root.querySelector('#rTitle').value.trim()||'Untitled source',sourceType:result.root.querySelector('#rType').value,author:result.root.querySelector('#rAuthor').value.trim(),publication:result.root.querySelector('#rPub').value.trim(),publishedAt:result.root.querySelector('#rDate').value.trim(),url:result.root.querySelector('#rUrl').value.trim(),quote:result.root.querySelector('#rQuote').value.trim(),notes:result.root.querySelector('#rNotes').value.trim(),tags:LF.parseTags(result.root.querySelector('#rTags').value)});app.navigate('research');}
  async function citationDialog(r){await LF.dialog({title:'Citation helper',body:`<label class="field">Style<select id="citeStyle"><option value="mla">MLA-like</option><option value="apa">APA-like</option><option value="chicago">Chicago-like</option></select></label><textarea id="citeOutput" rows="7" readonly>${LF.escapeHtml(LF.writer.citation(r,'mla'))}</textarea><p class="muted small">This is a convenience formatter, not a substitute for checking the current style manual.</p>`,confirmText:'Copy',onMount:root=>{const sel=root.querySelector('#citeStyle'),out=root.querySelector('#citeOutput');sel.onchange=()=>out.value=LF.writer.citation(r,sel.value);root.querySelector('.modal__footer [data-confirm]').onclick=()=>{LF.copyText(out.value);LF.toast('Citation copied.','success');root.remove();};}});}

  views.continuity=async app=>{const p=await app.activeProject();if(!p){app.root.innerHTML=empty('Choose a project','Continuity tracking belongs to a writing project.');return;}const issues=await LF.store.list('plotIssue',{projectId:p.id,sort:'updated-desc'});app.root.innerHTML=`<section class="view-page"><header class="view-header"><div><p class="eyebrow">Story integrity</p><h1>Continuity & plot issues</h1><p>Track contradictions, unresolved promises, timeline questions, character consistency, and research gaps.</p></div><div class="header-actions"><button id="scanContinuityBtn" class="button button--secondary" type="button">⌕ Scan manuscript</button><button id="newIssueBtn" class="button button--primary" type="button">＋ Issue</button></div></header><div class="issue-board">${['high','medium','low'].map(sev=>`<section class="issue-column"><h2>${sev[0].toUpperCase()+sev.slice(1)} <span>${issues.filter(i=>i.severity===sev&&i.status!=='resolved').length}</span></h2>${issues.filter(i=>i.severity===sev&&i.status!=='resolved').map(i=>issueCard(i)).join('')||'<p class="muted small">None open.</p>'}</section>`).join('')}</div><section class="panel resolved-panel"><div class="panel-heading"><h2>Resolved</h2></div>${issues.filter(i=>i.status==='resolved').map(i=>issueCard(i)).join('')||'<p class="muted">Resolved issues will appear here.</p>'}</section></section>`;$('#newIssueBtn').onclick=()=>issueDialog(app,p);$('#scanContinuityBtn').onclick=()=>continuityScan(app,p);app.root.onclick=async e=>{const edit=e.target.closest('[data-edit-issue]');if(edit)issueDialog(app,p,await LF.store.get('plotIssue',edit.dataset.editIssue));const res=e.target.closest('[data-resolve-issue]');if(res){const i=await LF.store.get('plotIssue',res.dataset.resolveIssue);await LF.store.put({...i,status:i.status==='resolved'?'open':'resolved',resolvedAt:i.status==='resolved'?'':LF.now()});app.navigate('continuity');}};};
  function issueCard(i){return `<article class="issue-card"><div class="issue-card__top"><span>${LF.escapeHtml(i.issueType||'continuity')}</span><button class="icon-button" data-edit-issue="${i.id}" type="button" aria-label="Edit issue">✎</button></div><h3>${LF.escapeHtml(i.title)}</h3><p>${LF.escapeHtml(i.description||'')}</p><div class="issue-card__bottom"><span>${LF.tagHtml(i.tags||[])}</span><button data-resolve-issue="${i.id}" type="button">${i.status==='resolved'?'Reopen':'Resolve'}</button></div></article>`;}
  async function issueDialog(app,p,i=null){const result=await LF.dialog({title:i?'Edit plot issue':'New plot issue',body:`<div class="form-grid"><label class="field">Title<input id="iTitle" value="${LF.escapeAttr(i?.title||'')}"></label><label class="field">Type<select id="iType">${['continuity','plot hole','character','timeline','world rule','research','promise/payoff','spelling','placeholder','other'].map(t=>`<option ${t===i?.issueType?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Severity<select id="iSeverity">${['high','medium','low'].map(s=>`<option ${s===(i?.severity||'medium')?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Status<select id="iStatus">${['open','investigating','resolved'].map(s=>`<option ${s===(i?.status||'open')?'selected':''}>${s}</option>`).join('')}</select></label><label class="field field--wide">Details<textarea id="iDesc" rows="5">${LF.escapeHtml(i?.description||'')}</textarea></label><label class="field field--wide">Tags<input id="iTags" value="${LF.escapeAttr((i?.tags||[]).join(', '))}"></label></div>`,confirmText:'Save issue',wide:true});if(!result)return;const rec=await LF.store.put({...i,type:'plotIssue',projectId:p.id,title:result.root.querySelector('#iTitle').value.trim()||'Untitled issue',issueType:result.root.querySelector('#iType').value,severity:result.root.querySelector('#iSeverity').value,status:result.root.querySelector('#iStatus').value,description:result.root.querySelector('#iDesc').value.trim(),tags:LF.parseTags(result.root.querySelector('#iTags').value)});if(LF.state.settings.privacy.backendEnabled&&LF.api.token)LF.api.pushRecord(rec).catch(()=>{});app.navigate('continuity');}
  async function continuityScan(app,p){const docs=await LF.store.list('document',{projectId:p.id}),entities=await LF.store.list('entity',{projectId:p.id}),timeline=await LF.store.list('timeline',{projectId:p.id});const findings=LF.writer.continuityScan({documents:docs,entities,timeline});if(!findings.length){LF.toast('No obvious local continuity flags found.','success');return;}const result=await LF.dialog({title:'Continuity scan results',wide:true,body:`<p>The local scan found ${findings.length} possible issues. These are prompts for review, not automatic claims that the manuscript is wrong.</p><div class="scan-findings">${findings.map((f,i)=>`<label><input type="checkbox" value="${i}" checked><span><strong>${LF.escapeHtml(f.title)}</strong><small>${LF.escapeHtml(f.description)}</small></span></label>`).join('')}</div>`,confirmText:'Add selected issues'});if(!result)return;const selected=[...result.root.querySelectorAll('.scan-findings input:checked')].map(x=>findings[Number(x.value)]);for(const f of selected)await LF.store.put({type:'plotIssue',projectId:p.id,...f,status:'open',tags:['auto-scan']});app.navigate('continuity');}

  views.language=async app=>{const p=await app.activeProject();if(!p){app.root.innerHTML=empty('Choose a project','Language notes belong to a writing project.');return;}const languages=await LF.store.list('language',{projectId:p.id,sort:'title-asc'}),lexicon=await LF.store.list('lexicon',{projectId:p.id,sort:'title-asc'});app.root.innerHTML=`<section class="view-page"><header class="view-header"><div><p class="eyebrow">Words & naming</p><h1>Language Lab</h1><p>Invented languages, terminology, naming conventions, pronunciation, style rules, and project lexicons.</p></div><div class="header-actions"><button id="newLanguageBtn" class="button button--secondary" type="button">＋ Language</button><button id="newWordBtn" class="button button--primary" type="button">＋ Word / term</button></div></header><div class="language-layout"><section class="panel"><div class="panel-heading"><h2>Languages & rule sets</h2></div>${languages.length?languages.map(l=>`<article class="language-card"><h3>${LF.escapeHtml(l.name)}</h3><p>${LF.escapeHtml(l.description||'')}</p><button data-edit-language="${l.id}" type="button">Edit rules</button></article>`).join(''):'<p class="muted">No language rule sets yet.</p>'}</section><section class="panel"><div class="panel-heading"><h2>Project lexicon</h2><input id="lexSearch" type="search" placeholder="Filter terms"></div><div id="lexTable" class="table-wrap"></div></section></div></section>`;const table=$('#lexTable');const render=()=>{const q=$('#lexSearch').value.toLowerCase(),list=lexicon.filter(x=>`${x.term} ${x.meaning||''} ${x.pronunciation||''}`.toLowerCase().includes(q));table.innerHTML=list.length?`<table><thead><tr><th>Term</th><th>Meaning</th><th>Pronunciation</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td><strong>${LF.escapeHtml(x.term)}</strong></td><td>${LF.escapeHtml(x.meaning||'')}</td><td>${LF.escapeHtml(x.pronunciation||'')}</td><td><button data-edit-word="${x.id}" type="button">Edit</button></td></tr>`).join('')}</tbody></table>`:'<p class="muted">No terms match.</p>';};render();$('#lexSearch').oninput=render;$('#newLanguageBtn').onclick=()=>languageDialog(app,p);$('#newWordBtn').onclick=()=>wordDialog(app,p,languages);app.root.onclick=async e=>{const l=e.target.closest('[data-edit-language]');if(l)languageDialog(app,p,await LF.store.get('language',l.dataset.editLanguage));const w=e.target.closest('[data-edit-word]');if(w)wordDialog(app,p,languages,await LF.store.get('lexicon',w.dataset.editWord));};};
  async function languageDialog(app,p,l=null){const result=await LF.dialog({title:l?'Edit language rules':'New language / naming system',wide:true,body:`<label class="field">Name<input id="lName" value="${LF.escapeAttr(l?.name||'')}"></label><label class="field">Description<textarea id="lDesc" rows="4">${LF.escapeHtml(l?.description||'')}</textarea></label><label class="field">Sound / pronunciation rules<textarea id="lSound" rows="4">${LF.escapeHtml(l?.rules?.sounds||'')}</textarea></label><label class="field">Grammar / structure rules<textarea id="lGrammar" rows="4">${LF.escapeHtml(l?.rules?.grammar||'')}</textarea></label><label class="field">Naming conventions<textarea id="lNames" rows="4">${LF.escapeHtml(l?.rules?.names||'')}</textarea></label>`,confirmText:'Save rules'});if(!result)return;const rec=await LF.store.put({...l,type:'language',projectId:p.id,name:result.root.querySelector('#lName').value.trim()||'Unnamed language',description:result.root.querySelector('#lDesc').value.trim(),rules:{sounds:result.root.querySelector('#lSound').value.trim(),grammar:result.root.querySelector('#lGrammar').value.trim(),names:result.root.querySelector('#lNames').value.trim()}});if(LF.state.settings.privacy.backendEnabled&&LF.api.token)LF.api.pushRecord(rec).catch(()=>{});app.navigate('language');}
  async function wordDialog(app,p,languages,w=null){const result=await LF.dialog({title:w?'Edit lexicon term':'New lexicon term',body:`<div class="form-grid"><label class="field">Term<input id="wTerm" value="${LF.escapeAttr(w?.term||'')}"></label><label class="field">Language<select id="wLang"><option value="">General project vocabulary</option>${languages.map(l=>`<option value="${l.id}" ${l.id===w?.languageId?'selected':''}>${LF.escapeHtml(l.name)}</option>`).join('')}</select></label><label class="field">Pronunciation<input id="wPron" value="${LF.escapeAttr(w?.pronunciation||'')}"></label><label class="field">Part of speech / type<input id="wPos" value="${LF.escapeAttr(w?.partOfSpeech||'')}"></label><label class="field field--wide">Meaning<input id="wMeaning" value="${LF.escapeAttr(w?.meaning||'')}"></label><label class="field field--wide">Notes<textarea id="wNotes" rows="4">${LF.escapeHtml(w?.notes||'')}</textarea></label><label class="field field--wide">Tags<input id="wTags" value="${LF.escapeAttr((w?.tags||[]).join(', '))}"></label></div>`,confirmText:'Save term',wide:true});if(!result)return;await LF.store.put({...w,type:'lexicon',projectId:p.id,term:result.root.querySelector('#wTerm').value.trim()||'Untitled term',languageId:result.root.querySelector('#wLang').value,pronunciation:result.root.querySelector('#wPron').value.trim(),partOfSpeech:result.root.querySelector('#wPos').value.trim(),meaning:result.root.querySelector('#wMeaning').value.trim(),notes:result.root.querySelector('#wNotes').value.trim(),tags:LF.parseTags(result.root.querySelector('#wTags').value)});app.navigate('language');}

  views.revision=async app=>{const p=await app.activeProject();const docs=p?await LF.store.list('document',{projectId:p.id,sort:'order'}):[];app.root.innerHTML=`<section class="view-page revision-view"><header class="view-header"><div><p class="eyebrow">Draft diagnostics</p><h1>Revision Lab</h1><p>Heuristic signals for readability, repetition, sentence rhythm, filler language, dialogue balance, and sensory distribution. These are aids, not style rules.</p></div></header><div class="revision-source"><label>Analyze <select id="revisionDoc"><option value="all">Entire manuscript</option>${docs.map(d=>`<option value="${d.id}">${LF.escapeHtml(d.title)}</option>`).join('')}</select></label><button id="runRevisionBtn" class="button button--primary" type="button">Analyze draft</button></div><div id="revisionResults">${docs.length?'<p class="muted">Choose a document or the whole manuscript, then run the local analysis.</p>':empty('No manuscript text','Add a chapter or scene before running revision analysis.')}</div></section>`;$('#runRevisionBtn').onclick=async()=>{const id=$('#revisionDoc').value;const selected=id==='all'?docs:[await LF.store.get('document',id)];const text=selected.map(d=>d.content||'').join(' '),a=LF.writer.analyze(text);renderRevision($('#revisionResults'),a,selected.length);};};
  function renderRevision(root,a,docCount){root.innerHTML=`<div class="revision-grid"><article class="analysis-card"><span>Words</span><strong>${a.stats.words.toLocaleString()}</strong><small>${docCount} document${docCount===1?'':'s'}</small></article><article class="analysis-card"><span>Readability</span><strong>${a.stats.flesch}</strong><small>${LF.writer.readabilityLabel(a.stats.flesch)}</small></article><article class="analysis-card"><span>Avg. sentence</span><strong>${a.stats.avgSentence}</strong><small>words</small></article><article class="analysis-card"><span>Sentence variation</span><strong>${a.sentenceVariation}</strong><small>standard deviation</small></article><article class="analysis-card"><span>Dialogue</span><strong>${a.dialogueRatio}%</strong><small>approximate word share</small></article><article class="analysis-card"><span>Reading time</span><strong>${a.stats.readingMinutes}</strong><small>minutes</small></article></div><div class="revision-panels"><section class="panel"><h2>Repeated content words</h2>${a.repeated.length?`<div class="metric-list">${a.repeated.map(x=>`<div><span>${LF.escapeHtml(x.word)}</span><meter min="0" max="${a.repeated[0].count}" value="${x.count}"></meter><strong>${x.count}</strong></div>`).join('')}</div>`:'<p class="muted">No high-frequency content words stood out.</p>'}</section><section class="panel"><h2>Filler / weak phrase candidates</h2>${a.phrases.length?`<div class="chip-list">${a.phrases.map(x=>`<span>${LF.escapeHtml(x.phrase)} · ${x.count}</span>`).join('')}</div>`:'<p class="muted">No common filler candidates detected.</p>'}</section><section class="panel"><h2>Adverb candidates</h2>${a.adverbs.length?`<div class="chip-list">${a.adverbs.map(x=>`<span>${LF.escapeHtml(x.word)} · ${x.count}</span>`).join('')}</div>`:'<p class="muted">No notable -ly adverb concentration.</p>'}</section><section class="panel"><h2>Possible passive constructions</h2>${a.passive.length?`<ol class="sentence-list">${a.passive.slice(0,12).map(s=>`<li>${LF.escapeHtml(s)}</li>`).join('')}</ol>`:'<p class="muted">No obvious passive-pattern candidates in this heuristic pass.</p>'}</section><section class="panel"><h2>Long sentences</h2>${a.longSentences.length?`<ol class="sentence-list">${a.longSentences.slice(0,10).map(s=>`<li>${LF.escapeHtml(s)}</li>`).join('')}</ol>`:'<p class="muted">No sentences over 35 words detected.</p>'}</section><section class="panel"><h2>Sensory language signals</h2><div class="sensory-grid">${Object.entries(a.sensory).map(([k,v])=>`<div><strong>${v}</strong><span>${k}</span></div>`).join('')}</div><p class="muted small">A low number is not automatically a problem; genre, viewpoint, scene purpose, and voice matter.</p></section></div>`;}

  views.assistant=async app=>{const p=await app.activeProject();app.root.innerHTML=`<section class="view-page assistant-view"><header class="view-header"><div><p class="eyebrow">Free local writer support</p><h1>Literary Assistant</h1><p>Search bundled literary and specialist corpora, build project-aware prompts, and run deterministic writing tools without requiring a paid AI service or misrepresenting retrieval data as a generative model.</p></div></header><div class="assistant-layout"><section class="assistant-chat panel"><div id="assistantMessages" class="assistant-messages"><div class="assistant-message assistant-message--system"><strong>Literary Assistant</strong><p>Ask for scene planning, prose analysis, research angles, continuity strategy, character questions, or a portable prompt. The core assistant is local and free.</p></div></div><form id="assistantForm" class="assistant-composer"><textarea id="assistantInput" rows="4" placeholder="Example: Help me plan a tense reunion scene while preserving limited third-person POV."></textarea><div class="assistant-options"><label><input id="includeCurrent" type="checkbox" checked> Include current document context</label><label><input id="includeExtended" type="checkbox"> Search extended specialist packs</label><button class="button button--primary" type="submit">Search & assist</button></div></form></section><aside class="assistant-side"><section class="panel"><h2>Project context</h2><p>${p?`${projectPill(p)}<br>${LF.escapeHtml(p.premise||'No premise saved yet.')}`:'No active project.'}</p></section><section class="panel"><h2>Fast tools</h2><div class="action-list"><button data-assist-fast="scene" type="button">Scene questions</button><button data-assist-fast="revision" type="button">Analyze current draft</button><button data-assist-fast="prompt" type="button">Build portable prompt</button><button data-assist-fast="research" type="button">Search corpus only</button></div></section><section class="panel corpus-status"><h2>Local corpus</h2><p id="corpusStatus">Core literary packs load only when searched. Extended packs are optional per search.</p></section></aside></div></section>`;const messages=$('#assistantMessages');const form=$('#assistantForm'),input=$('#assistantInput');form.onsubmit=async e=>{e.preventDefault();const q=input.value.trim();if(!q)return;await assistantTurn(app,q,messages,$('#includeCurrent').checked,$('#includeExtended').checked);input.value='';};$$('[data-assist-fast]').forEach(b=>b.onclick=()=>{const map={scene:'Give me scene-development questions for the current document.',revision:'Analyze the current draft for readability, repetition, rhythm, and revision signals.',prompt:'Build a portable, project-aware writing prompt for the current document.',research:'Search the local corpus for useful writing and research specialist patterns.'};input.value=map[b.dataset.assistFast];if(b.dataset.assistFast==='research')$('#includeExtended').checked=true;form.requestSubmit();});};
  async function assistantTurn(app,q,messages,includeCurrent=true,includeExtended=false){messages.insertAdjacentHTML('beforeend',`<div class="assistant-message assistant-message--user"><strong>You</strong><p>${LF.escapeHtml(q)}</p></div><div id="assistantWorking" class="assistant-message assistant-message--system"><strong>Literary Assistant</strong><p>Searching local tools and corpus…</p></div>`);messages.scrollTop=messages.scrollHeight;const current=includeCurrent?(LF.state.activeRecord||LF.editor.record||null):null;let local=LF.assistant.localResponse(q,current),refs=[];try{refs=await LF.assistant.search(q,{limit:LF.state.settings.assistant.maxResults||8,includeExtended});$('#corpusStatus').textContent=`Corpus ready · ${LF.assistant.index?.recordCount?.toLocaleString()||''} indexed records${includeExtended?' + extended specialist packs':''}`; }catch(err){$('#corpusStatus').textContent='Bundled corpus could not load. Core deterministic writing tools still work.';}const working=$('#assistantWorking');if(!working)return;working.removeAttribute('id');working.innerHTML=`<strong>${LF.escapeHtml(local.title)}</strong><p>${LF.escapeHtml(local.body).replace(/\n/g,'<br>')}</p>${refs.length?`<details><summary>${refs.length} relevant specialist patterns</summary><div class="assistant-results">${refs.map(r=>`<article><h3>${LF.escapeHtml(r.title)}</h3><p>${LF.escapeHtml(String(r.prompt||r.body||r.description||'').slice(0,900))}${String(r.prompt||r.body||r.description||'').length>900?'…':''}</p><small>${r._pack==='extended'?'extended specialist pack':'literary pack'}</small><button data-copy-pattern="${LF.escapeAttr(r.id||'')}" type="button">Copy pattern</button></article>`).join('')}</div></details>`:''}<div class="assistant-actions"><button data-build-prompt type="button">Build project-aware prompt</button></div>`;working.querySelectorAll('[data-copy-pattern]').forEach(b=>b.onclick=()=>{const r=refs.find(x=>String(x.id||'')===b.dataset.copyPattern);LF.copyText(r?.prompt||r?.body||r?.description||'');LF.toast('Pattern copied.','success');});working.querySelector('[data-build-prompt]').onclick=async()=>{const prompt=await LF.assistant.composePrompt(q,{record:current,includeExtended});await LF.dialog({title:'Portable project-aware prompt',wide:true,body:`<textarea id="portablePrompt" rows="20" readonly>${LF.escapeHtml(prompt)}</textarea>`,confirmText:'Copy prompt',onMount:root=>root.querySelector('.modal__footer [data-confirm]').onclick=()=>{LF.copyText(root.querySelector('#portablePrompt').value);LF.toast('Prompt copied.','success');root.remove();}});};messages.scrollTop=messages.scrollHeight;}

  views.trash=async app=>{const all=await LF.store.all({includeDeleted:true}),rows=all.filter(r=>r.deletedAt).sort((a,b)=>String(b.deletedAt).localeCompare(String(a.deletedAt)));app.root.innerHTML=`<section class="view-page"><header class="view-header"><div><p class="eyebrow">Recovery</p><h1>Recently Deleted</h1><p>Restore items or permanently remove them from this browser.</p></div></header>${rows.length?`<div class="record-list trash-list">${rows.map(r=>`<div class="record-row"><span class="record-icon">♲</span><span class="record-row__main"><strong>${LF.escapeHtml(r.title||r.name||r.term||'Untitled')}</strong><small>${LF.escapeHtml(r.type)} · deleted ${LF.relativeTime(r.deletedAt)}</small></span><button data-restore-key="${r.key}" class="button button--secondary" type="button">Restore</button><button data-purge-key="${r.key}" class="button button--danger" type="button">Delete forever</button></div>`).join('')}</div>`:empty('Trash is empty','Items moved to Recently Deleted will appear here.')}</section>`;app.root.onclick=async e=>{const restore=e.target.closest('[data-restore-key]');if(restore){const r=await LF.store.getKey(restore.dataset.restoreKey);await LF.store.restore(r.type,r.id);LF.toast('Item restored.','success');app.navigate('trash');}const purge=e.target.closest('[data-purge-key]');if(purge){const r=await LF.store.getKey(purge.dataset.purgeKey);if(await LF.confirm(`Permanently delete “${r.title||r.name||'this item'}”? This cannot be undone.`,'Delete forever',true)){await LF.store.hardDelete(r.type,r.id);app.navigate('trash');}}};};

  views.artstudio=async app=>{
    app.closeInspector();
    const studio=global.LiteraryFriend?.artStudio;
    if(!studio){app.root.innerHTML=empty('Art Studio unavailable','The integrated Art Studio module did not load.');return;}
    app.root.innerHTML=`<section class="view-page embedded-tool-view"><header class="view-header compact-tool-header"><div><p class="eyebrow">Book art & covers</p><h1><span class="brand-wordmark">LiteraryFriend</span> Art Studio</h1><p>Retro cover design, painting, layout, prompt refinement, and editable local concept art. No unsupported backend AI route is required.</p></div></header><div id="artStudioMount" class="art-studio-host"></div></section>`;
    await studio.mount(app.root.querySelector('#artStudioMount'));
  };

  views.cloud=async app=>{
    app.closeInspector();
    if(!global.LFBackendConsole){app.root.innerHTML=empty('Cloud tools unavailable','The backend console module did not load.');return;}
    await global.LFBackendConsole.mount(app.root,app);
  };

  views.docs=async app=>{
    app.closeInspector();
    const docs=global.LF_DOCS_CONTENT||{};const names=Object.keys(docs);const first=names[0]||'README';
    app.root.innerHTML=`<section class="view-page docs-view"><header class="view-header"><div><p class="eyebrow">Legal & project documentation</p><h1>Docs & Licenses</h1><p>These files are also present in the <code>docs/</code> folder. They are embedded here so attribution remains readable when LiteraryFriend is opened directly from a local file.</p></div></header><div class="docs-layout"><nav class="docs-tabs" aria-label="Documentation files">${names.map((n,i)=>`<button type="button" data-doc="${LF.escapeAttr(n)}" class="${i===0?'is-active':''}">${LF.escapeHtml(n)}</button>`).join('')}</nav><article class="panel docs-paper"><div class="docs-filebar"><strong id="docTitle">${LF.escapeHtml(first)}</strong><button id="copyDoc" class="button button--ghost" type="button">Copy</button></div><pre id="docBody" tabindex="0"></pre></article></div></section>`;
    const body=app.root.querySelector('#docBody'),title=app.root.querySelector('#docTitle');let active=first;const show=n=>{active=n;title.textContent=n;body.textContent=docs[n]||'';app.root.querySelectorAll('[data-doc]').forEach(b=>b.classList.toggle('is-active',b.dataset.doc===n));body.scrollTop=0;};show(first);app.root.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>show(b.dataset.doc));app.root.querySelector('#copyDoc').onclick=()=>{LF.copyText(docs[active]||'');LF.toast(`${active} copied.`,'success');};
  };

  views.bookbuilder=async app=>{
    app.closeInspector();
    if(!global.LFBookStudio){app.root.innerHTML=empty('Book Builder unavailable','The integrated Book Builder module did not load.');return;}
    await global.LFBookStudio.mount(app.root);
  };

  views.settings=async app=>{const s=LF.state.settings,a=s.accessibility,r=s.reading,e=s.editor;app.root.innerHTML=`<section class="view-page settings-view"><header class="view-header"><div><p class="eyebrow">Preferences</p><h1>Settings & accessibility</h1><p>LiteraryFriend is designed to remain usable with keyboard navigation, screen readers, large text, reduced motion, and high-contrast presentation.</p></div></header><div class="settings-grid"><section class="panel"><h2>Appearance</h2><label class="field">Theme<select id="setTheme"><option value="dark">Dark</option><option value="light">Light</option></select></label><label class="setting-toggle"><span><strong>High contrast</strong><small>Increase borders and text separation.</small></span><input id="setContrast" type="checkbox"></label><label class="setting-toggle"><span><strong>Reduce motion</strong><small>Disable decorative transitions and movement.</small></span><input id="setMotion" type="checkbox"></label><label class="setting-toggle"><span><strong>Large targets</strong><small>Increase button and input hit areas.</small></span><input id="setTargets" type="checkbox"></label></section><section class="panel"><h2>Reading comfort</h2><label class="field">Text scale <output id="fontScaleOut"></output><input id="setFontScale" type="range" min="0.85" max="1.8" step="0.05"></label><label class="field">Line height <output id="lineHeightOut"></output><input id="setLineHeight" type="range" min="1.2" max="2.2" step="0.05"></label><label class="field">Reading width <output id="textWidthOut"></output><input id="setTextWidth" type="range" min="45" max="110" step="1"></label><label class="setting-toggle"><span><strong>Dyslexia-friendly mode</strong><small>Uses a broad system sans-serif stack, stronger spacing, and fewer decorative forms.</small></span><input id="setDyslexia" type="checkbox"></label></section><section class="panel"><h2>Read aloud</h2><label class="field">Speech rate <output id="speechRateOut"></output><input id="setSpeechRate" type="range" min="0.5" max="2" step="0.05"></label><label class="field">Voice<select id="setVoice"><option value="">System default</option>${LF.a11y.refreshVoices().map(v=>`<option value="${LF.escapeAttr(v.name)}">${LF.escapeHtml(v.name)} · ${LF.escapeHtml(v.lang)}</option>`).join('')}</select></label><div class="button-row"><button id="testVoice" class="button button--secondary" type="button">▶ Test voice</button><button id="stopVoice" class="button button--ghost" type="button">■ Stop</button></div></section><section class="panel"><h2>Editor</h2><label class="setting-toggle"><span><strong>Autosave</strong><small>Save edits to IndexedDB while writing.</small></span><input id="setAutosave" type="checkbox"></label><label class="setting-toggle"><span><strong>Spellcheck</strong><small>Use the browser's spelling support.</small></span><input id="setSpell" type="checkbox"></label><label class="field">Session word goal<input id="setSessionGoal" type="number" min="0" step="50"></label><label class="field">Daily word goal<input id="setDailyGoal" type="number" min="0" step="50"></label></section><section class="panel"><h2>Backend & account</h2><p class="small muted">Endpoint: ${LF.escapeHtml(LF.API_CONFIG.endpoint)}</p><label class="setting-toggle"><span><strong>Enable backend sync</strong><small>Local saving always remains available.</small></span><input id="setBackend" type="checkbox"></label><div id="accountPanel"></div><div class="button-row"><button id="accountBtn" class="button button--secondary" type="button">${LF.api.token?'Account':'Sign in / register'}</button>${LF.api.token?'<button id="logoutBtn" class="button button--ghost" type="button">Sign out</button>':''}</div></section><section class="panel"><h2>Data portability</h2><p>Export the entire local LiteraryFriend record set as JSON, import a previous export, or clear local data.</p><div class="action-list"><button id="exportAllBtn" type="button">Export all local data</button><button id="importAllBtn" type="button">Import data or document</button><button id="resetLocalBtn" class="danger-text" type="button">Reset local LiteraryFriend data</button></div></section></div></section>`;
    const set=(id,val)=>{$(`#${id}`).value=val;},check=(id,val)=>{$(`#${id}`).checked=!!val;};set('setTheme',s.appearance.theme);check('setContrast',a.highContrast);check('setMotion',a.reduceMotion);check('setTargets',a.largeTargets);set('setFontScale',a.fontScale);set('setLineHeight',a.lineHeight);set('setTextWidth',a.textWidth);check('setDyslexia',a.dyslexiaFriendly);set('setSpeechRate',r.rate);set('setVoice',r.voice||'');check('setAutosave',e.autosave);check('setSpell',e.spellcheck);set('setSessionGoal',e.sessionGoal);set('setDailyGoal',e.dailyGoal);check('setBackend',s.privacy.backendEnabled);const updateOutputs=()=>{$('#fontScaleOut').textContent=`${Math.round(Number($('#setFontScale').value)*100)}%`;$('#lineHeightOut').textContent=$('#setLineHeight').value;$('#textWidthOut').textContent=`${$('#setTextWidth').value} characters`;$('#speechRateOut').textContent=`${$('#setSpeechRate').value}×`;};updateOutputs();$$('input,select',app.root).forEach(input=>input.addEventListener('change',async()=>{s.appearance.theme=$('#setTheme').value;a.highContrast=$('#setContrast').checked;a.reduceMotion=$('#setMotion').checked;a.largeTargets=$('#setTargets').checked;a.fontScale=Number($('#setFontScale').value);a.lineHeight=Number($('#setLineHeight').value);a.textWidth=Number($('#setTextWidth').value);a.dyslexiaFriendly=$('#setDyslexia').checked;r.rate=Number($('#setSpeechRate').value);r.voice=$('#setVoice').value;e.autosave=$('#setAutosave').checked;e.spellcheck=$('#setSpell').checked;e.sessionGoal=Number($('#setSessionGoal').value||0);e.dailyGoal=Number($('#setDailyGoal').value||0);s.privacy.backendEnabled=$('#setBackend').checked;updateOutputs();await app.saveSettings();app.updateConnection();}));$$('input[type="range"]',app.root).forEach(x=>x.addEventListener('input',updateOutputs));$('#testVoice').onclick=()=>LF.a11y.speak('LiteraryFriend read aloud is ready. Adjust the speech rate and voice until listening feels comfortable.','voice test');$('#stopVoice').onclick=()=>LF.a11y.stop();$('#accountBtn').onclick=()=>app.authDialog();$('#logoutBtn')?.addEventListener('click',async()=>{await LF.api.logout();app.updateConnection();app.navigate('settings');});$('#exportAllBtn').onclick=async()=>{const pack=await LF.store.exportAll();LF.download(`literaryfriend-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(pack,null,2),'application/json');};$('#importAllBtn').onclick=()=>$('#importInput').click();$('#resetLocalBtn').onclick=async()=>{if(await LF.confirm('Delete all local LiteraryFriend records, attachments, settings, and drafts from this browser? Export first if you may need them.','Reset local data',true)){await LF.store.clearAll();location.reload();}};$('#accountPanel').innerHTML=LF.api.user?`<p><strong>${LF.escapeHtml(LF.api.user.displayName||LF.api.user.email||'Connected user')}</strong><br><span class="muted">${LF.escapeHtml(LF.api.user.email||'')}</span></p>`:'<p class="muted">No backend account is signed in.</p>';
  };

  views.editor=async(app,{record})=>{await LF.editor.mount(record,{container:app.root});};

  views.search=async(app,{query})=>{const all=await LF.store.all();const q=query.toLowerCase(),tokens=LF.tokenize(query);const scored=all.filter(r=>!['snapshot','attachment'].includes(r.type)).map(r=>{const hay=`${r.title||r.name||r.term||''} ${LF.stripHtml(r.content||'')} ${r.description||''} ${r.notes||''} ${(r.tags||[]).join(' ')}`.toLowerCase();let score=0;tokens.forEach(t=>{if((r.title||r.name||'').toLowerCase().includes(t))score+=5;if((r.tags||[]).some(x=>x.toLowerCase().includes(t)))score+=3;if(hay.includes(t))score+=1;});return{r,score};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,100);app.root.innerHTML=`<section class="view-page"><header class="view-header"><div><p class="eyebrow">Global search</p><h1>Results for “${LF.escapeHtml(query)}”</h1><p>${scored.length} local result${scored.length===1?'':'s'} across writing, notes, research, entities, and planning.</p></div></header>${scored.length?`<div class="search-results">${scored.map(({r})=>`<button class="search-result" data-search-key="${r.key}" type="button"><span class="record-icon">${recordIcon(r)}</span><span><strong>${LF.escapeHtml(r.title||r.name||r.term||'Untitled')}</strong><small>${LF.escapeHtml(r.type)} · ${LF.escapeHtml(LF.stripHtml(r.content||r.description||r.notes||r.meaning||'').slice(0,180))}</small></span><span>${LF.tagHtml((r.tags||[]).slice(0,4))}</span></button>`).join('')}</div>`:empty('No matching local records','Try a broader search phrase or search the Literary Assistant corpus instead.')}</section>`;app.root.onclick=async e=>{const b=e.target.closest('[data-search-key]');if(!b)return;const r=await LF.store.getKey(b.dataset.searchKey);if(['document','note'].includes(r.type))app.openRecord(r);else if(r.type==='project'){await app.setActiveProject(r.id);app.navigate('home');}else if(r.type==='entity')app.navigate(r.entityType==='character'?'characters':'world');else if(r.type==='research')app.navigate('research');else if(r.type==='plotIssue')app.navigate('continuity');else if(r.type==='timeline')app.navigate('timeline');else if(['language','lexicon'].includes(r.type))app.navigate('language');};};

  LF.app=new App();
  document.addEventListener('DOMContentLoaded',()=>LF.app.init().catch(err=>{console.error(err);document.getElementById('viewRoot').innerHTML=`<div class="fatal-error"><h1>LiteraryFriend could not start</h1><p>${LF.escapeHtml(err.message)}</p><button onclick="location.reload()">Reload</button></div>`;}));
})(window);
